<script setup>
import { computed, ref, watch } from 'vue';
import { brewApi } from '../api';
import { IONS,SALTS,PRESETS,emptyWater,emptyIons,emptyStage,copy,sourceSnapshot,calculateWater,defaultWaterTarget } from '../water-chemistry';
import WaterTargetPage from './WaterTargetPage.vue';
import WaterIonFields from './WaterIonFields.vue';
import JourneyDetailDialog from './JourneyDetailDialog.vue';
const props=defineProps({modelValue:Object,factoryId:[String,Number],productId:[String,Number],mashVolume:Number,spargeVolume:Number,readOnly:Boolean});
const emit=defineEmits(['update:modelValue']);
const water=computed(()=>props.modelValue);
const sources=ref([]),loading=ref(false),loadError=ref(''),stage=ref('mash'),modal=ref(''),sourceDraft=ref(null),targetDraft=ref(null),formError=ref('');
let seq=0,targetSeq=0;
const targets=ref([]),targetLoading=ref(false),targetError=ref(''),canManageTargets=ref(false);
const current=computed(()=>water.value.stages[stage.value]);
const volume=computed(()=>stage.value==='mash'?props.mashVolume:props.spargeVolume);
const calculation=computed(()=>{try{return {result:calculateWater(water.value,current.value,volume.value),error:''};}catch(e){return {result:null,error:e.message};}});
const result=computed(()=>calculation.value.result);
const fmt=v=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:2});
const statuses={ok:'范围内',low:'偏低',high:'偏高',unset:'未设目标',unknown:'需检测'};
const targetUpdated=computed(()=>water.value.target?.id&&targets.value.some(t=>t.id===water.value.target.id&&t.version!==water.value.target.version));
const targetCount=computed(()=>Object.values(result.value?.comparison||{}).filter(v=>v.status!=='unset').length);
const deviations=computed(()=>Object.values(result.value?.comparison||{}).filter(v=>['high','low'].includes(v.status)).length);
function chooseSource(id){const source=sources.value.find(s=>s.id===id);if(source){water.value.source=sourceSnapshot(source);water.value.source_mode='factory';water.value.override_note='';}}
async function loadSources(){const id=++seq;loadError.value='';sources.value=[];if(!props.factoryId)return;loading.value=true;try{const data=await brewApi.getWaterSources(props.factoryId);if(id!==seq)return;sources.value=data.items.filter(s=>s.active);if(!props.readOnly&&(!water.value.source||String(water.value.source.factory_id)!==String(props.factoryId))){const source=sources.value.find(s=>s.is_default)||sources.value[0];if(source)chooseSource(source.id);else water.value.source=null;}}catch(e){if(id===seq)loadError.value=e.message;}finally{if(id===seq)loading.value=false;}}
watch(()=>props.factoryId,loadSources,{immediate:true});
function chooseTarget(identifier){const target=targets.value.find(t=>t.id===identifier);if(!target)return;water.value.target=copy(Object.fromEntries(['id','name','product_id','product_name','factory_id','factory_name','version','ions','notes'].map(k=>[k,target[k]??null])));water.value.target_mode='library';}
async function loadTargets(){
 const id=++targetSeq;targetError.value='';targets.value=[];
 if(!props.productId||!props.factoryId)return;
 targetLoading.value=true;
 try{
  const data=await brewApi.getWaterTargets({product_id:props.productId,factory_id:props.factoryId});if(id!==targetSeq)return;
  targets.value=data.items.filter(t=>t.active);canManageTargets.value=data.can_manage;
  if(props.readOnly)return;
  const target=water.value.target;
  const mismatch=target?.id&&(String(target.product_id)!==String(props.productId)||(target.factory_id&&String(target.factory_id)!==String(props.factoryId)));
  if(mismatch){water.value.target=copy(PRESETS[1]);water.value.target_mode='reference';}
  if(!water.value.target?.id&&water.value.target_mode==='reference'){
   const preferred=defaultWaterTarget(targets.value,props.productId,props.factoryId);
   if(preferred)chooseTarget(preferred.id);
  }
 }catch(e){if(id===targetSeq)targetError.value=e.message;}finally{if(id===targetSeq)targetLoading.value=false;}
}
watch(()=>[props.productId,props.factoryId],loadTargets,{immediate:true});
function closeTargetManager(){modal.value='';loadTargets();}
function enable(event){water.value.enabled=event.target.checked;}
function editSource(){formError.value='';sourceDraft.value=water.value.source?copy(water.value.source):{name:'本配方临时原水',factory_id:String(props.factoryId),ions:emptyIons(),ph:'',alkalinity:''};modal.value='source';}
function saveSource(){if(!water.value.override_note?.trim()){formError.value='请填写本次原水修改依据。';return;}try{calculateWater({...water.value,source:sourceDraft.value},emptyStage(),1);water.value.source=copy(sourceDraft.value);water.value.source_mode='override';modal.value='';}catch(e){formError.value=e.message;}}
function editTarget(){targetDraft.value=copy(water.value.target);targetDraft.value.ions||={};for(const k of Object.keys(IONS))targetDraft.value.ions[k]||={min:'',max:''};modal.value='target';}
function applyDraftPreset(index){targetDraft.value=copy(PRESETS[Number(index)]);}
function saveTarget(){if(!targetDraft.value.name?.trim()){formError.value='请填写目标方案名称。';return;}for(const [key,bounds] of Object.entries(targetDraft.value.ions)){if(bounds.min!==''&&bounds.max!==''&&Number(bounds.min)>Number(bounds.max)){formError.value=`${IONS[key]}下限不能大于上限`;return;}}water.value.target=copy(targetDraft.value);water.value.target_mode='override';modal.value='';}
function copyToOther(){water.value.stages[stage.value==='mash'?'sparge':'mash']=copy(current.value);const other=stage.value==='mash'?props.spargeVolume:props.mashVolume;const dest=water.value.stages[stage.value==='mash'?'sparge':'mash'];if(volume.value>0){for(const salt of Object.values(dest.additions))salt.amount=Number((Number(salt.amount||0)*other/volume.value).toFixed(4));dest.acid.amount_ml=Number((Number(dest.acid.amount_ml||0)*other/volume.value).toFixed(4));}}
</script>
<template>
<section class="water-designer">
  <header class="water-design-heading"><h3>酿造水调节</h3><label class="water-enable"><input type="checkbox" :checked="water.enabled" :disabled="readOnly" @change="enable">启用</label></header>
  <div v-if="!water.enabled" class="water-disabled"><strong>本配方尚未启用酿造水调节</strong><p>启用后配置原水与投加量。</p></div>
  <template v-else>
    <div v-if="loadError" class="master-error">{{ loadError }}</div>
    <div class="water-context-cards">
      <section class="water-context-card"><header><small>原水档案</small><button v-if="!readOnly" type="button" class="water-link" @click="editSource">修改</button></header><select v-if="!readOnly" :value="water.source?.id||''" :disabled="loading||!factoryId" aria-label="配方使用的水源" @change="chooseSource($event.target.value)"><option value="" disabled>{{ loading?'加载中…':'请选择酒厂水源' }}</option><option v-for="s in sources" :key="s.id" :value="s.id">{{ s.name }}</option></select><strong v-else>{{ water.source?.name || '请选择酒厂水源' }}</strong><footer><span>{{ water.source_mode==='override'?'本配方已调整':water.source?.measured_on||'尚无检测日期' }}</span><button type="button" class="water-link" @click="modal='dilution'">{{ Number(water.dilution_percent)>0?`稀释 ${water.dilution_percent}%`:'设置稀释' }}</button></footer></section>
      <section class="water-context-card"><header><small>目标方案</small><button type="button" class="water-link" @click="editTarget();formError=''">{{ readOnly?'查看':'调整' }}</button></header><button type="button" class="water-context-name" @click="editTarget();formError=''">{{ water.target.name }} <span>⌄</span></button><footer><span>{{ water.target_mode==='library'?'酒品方案':water.target_mode==='override'?'本配方自定义':'参考模板' }}</span><button v-if="!readOnly && canManageTargets" type="button" class="water-link" @click="modal='target-manager'">管理酒品方案</button></footer></section>
    </div>
    <p v-if="!water.source" class="water-caption warning">请选择酒厂水源，或手动填写原水。未知离子不会按零处理。<button v-if="!readOnly" type="button" class="water-link" @click="editSource">填写原水</button></p>
    <nav class="water-stage-tabs" aria-label="处理水体"><button v-for="[key,label,v] in [['mash','糖化水',mashVolume],['sparge','洗糟水',spargeVolume]]" :key="key" type="button" :class="{active:stage===key}" @click="stage=key">{{ label }} <b>{{ fmt(v) }} L</b></button></nav>
    <div class="water-workspace">
      <section class="water-additions">
        <header class="water-card-heading"><h4>投加量</h4></header>
        <fieldset :disabled="readOnly" class="water-doses"><div v-for="(salt,key) in SALTS" :key="key" class="water-dose-row"><strong :title="salt.formula">{{ salt.name }}</strong><label><input v-model.number="current.additions[key].amount" type="number" min="0" step="any" :aria-label="salt.name+'投加量'"><span>g</span></label></div><div class="water-dose-row"><strong>乳酸</strong><label><input v-model.number="current.acid.amount_ml" type="number" min="0" step="any" aria-label="乳酸投加量"><span>mL</span></label></div>
        <details class="water-advanced"><summary>纯度与酸浓度</summary><div v-for="(salt,key) in SALTS" :key="key" class="water-dose-row"><span>{{ salt.name }}</span><label><input v-model.number="current.additions[key].purity" type="number" min="0.001" max="100" step="any" :aria-label="salt.name+'纯度'"><span>%</span></label></div><div class="water-dose-row"><span>乳酸质量浓度</span><label><input v-model.number="current.acid.concentration" type="number" min="0.001" max="100" step="any" aria-label="乳酸质量浓度"><span>%</span></label></div><div class="water-dose-row"><span>乳酸密度</span><label><input v-model.number="current.acid.density" type="number" min="0.001" max="3" step="0.001" aria-label="乳酸密度"><span>g/mL</span></label></div><p class="water-caption">按实际产品规格核对水合物、纯度、酸浓度与密度。</p></details></fieldset>
        <button v-if="!readOnly" type="button" class="water-link water-copy" :disabled="!volume" @click="copyToOther">按此浓度应用到{{ stage==='mash'?'洗糟水':'糖化水' }} →</button>
      </section>
      <section class="water-results">
        <header class="water-card-heading"><h4>预计调整结果 <small>mg/L</small></h4><span class="water-result-unit">原水 → 调整后 → 目标</span></header>
        <p v-if="targetUpdated && !readOnly" class="water-caption warning">目标库已更新。<button type="button" class="water-link" @click="chooseTarget(water.target.id)">引用最新范围</button></p>
        <p v-if="targetError" class="water-caption warning">{{ targetError }}</p>
        <p v-if="calculation.error" class="water-caption warning">{{ calculation.error }}</p>
        <template v-if="result">
          <div class="water-comparison-wrap"><table class="water-comparison"><thead><tr><th>参数</th><th>{{ Number(water.dilution_percent)>0?'混合原水':'原水' }}</th><th>调整后</th><th>目标</th></tr></thead><tbody><tr v-for="(label,key) in IONS" :key="key"><td>{{ label }}</td><td>{{ fmt(result.comparison[key].before) }}</td><td class="water-final"><strong>{{ fmt(result.comparison[key].after) }}</strong><span v-if="['high','low','unknown'].includes(result.comparison[key].status)" :class="['ion-status',result.comparison[key].status]">{{ statuses[result.comparison[key].status] }}</span></td><td class="water-range">{{ result.comparison[key].min??'—' }} ～ {{ result.comparison[key].max??'—' }}</td></tr></tbody></table></div>
          <div class="water-result-footer"><span :class="{warning:deviations}">{{ !targetCount?'未设置目标':deviations?deviations+' 项偏离目标':'已设目标项在范围内' }}</span><span>SO₄ : Cl <b>{{ fmt(result.ratio) }}</b></span></div>
          <details class="water-advanced water-parameters"><summary>其他水质参数</summary><dl><div><dt>原水总碱度 · CaCO₃</dt><dd>{{ fmt(water.source?.alkalinity) }} mg/L</dd></div><div><dt>原水 pH</dt><dd>{{ fmt(water.source?.ph) }}</dd></div><div><dt>调整后总硬度 · CaCO₃</dt><dd>{{ fmt(result.hardness) }} mg/L</dd></div><div><dt>估算剩余碱度 · CaCO₃</dt><dd>{{ fmt(result.alkalinity_estimate) }} mg/L</dd></div><div><dt>水源检测日期</dt><dd>{{ water.source?.measured_on || '未记录' }}</dd></div></dl><p v-if="water.override_note" class="water-caption">修改依据：{{ water.override_note }}</p></details>
          <div v-if="result.warnings.length" class="water-active-warnings" role="status"><p v-for="warning in result.warnings" :key="warning">{{ warning }}</p></div>
        </template>
      </section>
    </div>
    <details class="water-advanced water-calculation-help"><summary>计算说明</summary><p>本页为预计值，生产时需实测；不能直接预测糖化醪 pH。糖化水与洗糟水分别计算，水量来自对应工艺设置。目标和原水修改只保存在本配方，SO₄ : Cl 需结合绝对浓度判断。</p></details>
  </template>
<JourneyDetailDialog v-if="modal==='target-manager'" title="管理酒品目标水质方案" subtitle="维护方案后，返回配方选择要引用的目标；已保存的配方快照不会被覆盖。" @close="closeTargetManager"><WaterTargetPage :initial-product-id="productId" :initial-factory-id="factoryId" @changed="loadTargets" /></JourneyDetailDialog><JourneyDetailDialog v-if="modal==='source'" title="本配方原水调整" subtitle="仅调整当前配方的原水快照，不改变酒厂水源档案。" @close="modal=''"><form @submit.prevent="saveSource"><WaterIonFields :quality="sourceDraft" /><label class="water-modal-label">修改依据<textarea v-model.trim="water.override_note" required placeholder="例如：当日检测数据或特定水处理条件"></textarea></label><p v-if="formError" class="master-error">{{ formError }}</p><button class="btn btn-primary" type="submit">应用到本配方</button></form></JourneyDetailDialog><JourneyDetailDialog v-if="modal==='target'" title="目标水质方案" subtitle="酒款目标由酿酒师确认；参考范围不是所有同类啤酒必须遵守的固定标准。" @close="modal=''"><form @submit.prevent="saveTarget"><fieldset class="water-target-fields" :disabled="readOnly"><label v-if="!readOnly" class="water-modal-label">酒品目标方案<select :value="water.target_mode==='library'?water.target.id||'':''" :disabled="targetLoading||!targets.length" aria-label="选择本酒品的目标方案" @change="chooseTarget($event.target.value);editTarget()"><option value="" disabled>{{ targets.length?'选择已保存的方案':'暂无已保存方案' }}</option><option v-for="target in targets" :key="target.id" :value="target.id">{{ target.name }} · {{ target.factory_name }}</option></select></label><button v-if="!readOnly && canManageTargets" type="button" class="water-link" @click="modal='target-manager'">管理酒品方案 →</button><div v-if="!readOnly" class="water-target-reference"><label class="water-modal-label">从通用参考模板起步（可选）<select aria-label="引用通用参考模板" @change="applyDraftPreset($event.target.value)"><option value="" disabled selected>选择参考模板</option><option v-for="(p,i) in PRESETS" :key="p.name" :value="i">{{ p.name }}</option></select></label><p>参考模板不属于已保存的酒品方案。引用后可调整范围，保存仅应用于本配方。</p></div><label class="water-modal-label">方案名称<input v-model.trim="targetDraft.name" required></label><table class="water-comparison"><thead><tr><th>离子</th><th>下限 mg/L</th><th>上限 mg/L</th></tr></thead><tbody><tr v-for="(label,key) in IONS" :key="key"><td>{{ label }}</td><td><input v-model.number="targetDraft.ions[key].min" type="number" min="0" step="any"></td><td><input v-model.number="targetDraft.ions[key].max" type="number" min="0" step="any"></td></tr></tbody></table><p v-if="formError" class="master-error">{{ formError }}</p><button v-if="!readOnly" class="btn btn-primary" type="submit">保存目标范围</button></fieldset></form></JourneyDetailDialog><JourneyDetailDialog v-if="modal==='dilution'" title="稀释水设置" subtitle="使用 RO 水稀释时也应填写检测值；以下零值明确代表零离子假设。" @close="modal=''"><fieldset :disabled="readOnly" class="water-doses"><label class="water-modal-label">稀释水占本阶段总水量（%）<input v-model.number="water.dilution_percent" type="number" min="0" max="100" step="any"></label><WaterIonFields :quality="{ions:water.dilution_ions}" :extras="false" /><label class="water-modal-label">稀释水总碱度（mg/L，以 CaCO₃ 计）<input v-model.number="water.dilution_alkalinity" type="number" min="0" step="any"></label><p class="water-caption">当前阶段：原水 {{ fmt(result?.source_volume_l) }} L + 稀释水 {{ fmt(result?.dilution_volume_l) }} L = {{ fmt(volume) }} L</p></fieldset></JourneyDetailDialog></section></template>
<style scoped>
.water-context-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:12px}.water-context-card{padding:12px 15px;border:1px solid var(--border-default);border-radius:7px;min-width:0;background:var(--bg-surface)}.water-context-card header,.water-context-card footer{display:flex;align-items:center;justify-content:space-between;gap:10px}.water-context-card header small{font-size:10px;color:var(--text-muted)}.water-context-card .water-link{font-size:10px;padding:0}.water-context-card select,.water-context-name{box-sizing:border-box;width:100%;min-height:32px;margin:5px 0;padding:5px 0;font:inherit;font-size:13px;font-weight:500;color:var(--text-primary);border:0;background:transparent;text-align:left;cursor:pointer;text-overflow:ellipsis;overflow:hidden;white-space:nowrap}.water-context-card select{padding-right:20px}.water-context-name{display:flex;align-items:center;justify-content:space-between}.water-context-name span{color:var(--text-muted)}.water-context-card footer{font-size:10px;color:var(--text-muted);min-height:18px}.water-result-unit{font-size:10px;color:var(--text-muted)}@media(max-width:600px){.water-context-cards{gap:8px}.water-context-card{padding:10px}.water-context-card footer{align-items:flex-start;flex-direction:column;gap:3px}.water-context-card select,.water-context-name{font-size:12px}}

