ight:400;color:var(--text-muted);margin-left:8px}.water-target-chip{font-size:11px;max-width:250px;text-align:left}.water-doses,.water-target-fields{border:0;padding:0;margin:0;min-width:0}.water-dose-row{display:grid;grid-template-columns:minmax(0,1fr) 118px;gap:12px;align-items:center;min-height:54px;border-bottom:1px solid var(--border-subtle)}.water-dose-row>strong{font-size:12px;font-weight:500}.water-dose-row>span{font-size:11px;color:var(--text-secondary)}.water-dose-row label{display:flex!important;align-items:center;gap:8px!important;margin:0!important;min-width:0}.water-dose-row input{width:100%!important;min-width:0!important;min-height:34px!important;padding:6px 8px!important;background:var(--bg-input)!important;border:1px solid var(--border-default)!important;border-radius:5px!important;color:var(--text-primary)!important;text-align:right;font-size:13px!important}.water-dose-row label span{font-size:11px;color:var(--text-muted);min-width:20px}.water-advanced{font-size:11px;color:var(--text-muted);margin-top:16px}.water-advanced summary{cursor:pointer;list-style-position:inside;width:fit-content;padding:4px 0}.water-advanced summary:focus-visible{outline:2px solid var(--accent-gold);outline-offset:3px}.water-advanced p{line-height:1.8;margin:10px 0}.water-copy{margin-top:14px;font-size:11px}.water-comparison-wrap{overflow:auto}.water-comparison{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums}.water-comparison th{text-align:right;font-weight:400;color:var(--text-muted);font-size:11px;padding:10px 12px;border-bottom:1px solid var(--border-default);white-space:nowrap}.water-comparison td{text-align:right;padding:14px 12px;border-bottom:1px solid var(--border-subtle);white-space:nowrap}.water-comparison th:first-child,.water-comparison td:first-child{text-align:left;padding-left:0}.water-comparison td:first-child{font-size:12px}.water-final{background:#d4a85309}.water-final strong{font-size:20px;font-weight:600;color:#e6c